CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE guideline_documents(document_id TEXT PRIMARY KEY, document_title TEXT NOT NULL, authority TEXT NOT NULL, legal_basis TEXT, effective_date DATE, status TEXT, source_file TEXT, pages INT, source_type TEXT, sha256 TEXT NOT NULL, processed_at TIMESTAMPTZ, notes TEXT);
CREATE TABLE guideline_sections(section_id TEXT PRIMARY KEY, document_id TEXT REFERENCES guideline_documents(document_id), section_number INT, section_title TEXT, page_start INT, page_end INT, section_text_exact TEXT NOT NULL);
CREATE TABLE guideline_rules(rule_id TEXT PRIMARY KEY, document_id TEXT REFERENCES guideline_documents(document_id), section_id TEXT REFERENCES guideline_sections(section_id), rule_number INT, rule_title TEXT, rule_text_exact_from_pdf TEXT NOT NULL, rule_type TEXT, deterministic BOOLEAN, condition_json JSONB, action TEXT, source_page INT, source_reference TEXT, status TEXT);
CREATE TABLE guideline_chunks(chunk_id TEXT PRIMARY KEY, document_id TEXT REFERENCES guideline_documents(document_id), section_id TEXT REFERENCES guideline_sections(section_id), rule_id TEXT REFERENCES guideline_rules(rule_id), chunk_index INT, chunk_text TEXT NOT NULL, retrieval_text TEXT NOT NULL, metadata_json JSONB, source_page INT, source_reference TEXT, language TEXT, embedding vector(1024));
CREATE INDEX guideline_chunks_embedding_hnsw ON guideline_chunks USING hnsw (embedding vector_cosine_ops);
